alter table public.online_shops add column hours_display text check(hours_display is null or length(hours_display)<=1000), add column naver_map_url text check(naver_map_url is null or (length(naver_map_url)<=2000 and naver_map_url ~ '^https://[^[:space:]]+$')), add column google_map_url text check(google_map_url is null or (length(google_map_url)<=2000 and google_map_url ~ '^https://[^[:space:]]+$'));
